"""Original electrolyte chapter: potassium homeostasis and emergencies."""
from qbank_authoring import question,ref,finalize
HK=ref('UK Kidney Association: Treatment of Acute Hyperkalaemia in Adults, current guideline page','https://www.ukkidney.org/health-professionals/guidelines/treatment-acute-hyperkalaemia-adults-0')
RC=ref('Resuscitation Council UK: Special Circumstances Guidelines, 2025','https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines')
GS=ref('KDIGO Gitelman Syndrome Consensus','https://kdigo.org/wp-content/uploads/2017/02/KDIGO-Gitelman-conf-report.pdf')
EL=ref('Queensland Health: Electrolyte Disturbances, Adult Treatment Guidance','https://www.health.qld.gov.au/clinical-practice/guidelines-procedures/medicines/safety/electrolyte-disturbances/hypo')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Potassium is 6.8 mmol/L in a visibly hemolyzed specimen from an asymptomatic patient with normal kidney function. What is the best next principle?', 'Urgently reassess with an appropriately collected sample and ECG while judging the need for immediate treatment',[
 ('Ignore the result because all hemolyzed samples are harmless','True hyperkalemia can coexist and dangerous values require prompt assessment.'),('Always give insulin before any clinical assessment','Treatment of a spurious value can cause harm; assess urgency and confirm promptly.'),('A normal ECG definitively excludes dangerous hyperkalemia','ECG sensitivity is inadequate for exclusion.')],
 'Confirm suspected artifact without overlooking a real emergency', '**Hemolysis releases intracellular potassium in vitro.**',['Thrombocytosis, leukocytosis and collection technique can also cause artifacts.','Severe clinical or ECG findings should trigger treatment without waiting.'], '**Interpret the repeat value in context.**',['Use correct sampling and rapid processing.','Review medications, renal function and acid-base status.'],[['Artifact clue','Hemolyzed specimen'],['Immediate assessment','ECG and clinical state'],['Confirmation','Prompt correctly collected sample']],[HK],'clinical_scenario')
q('Severe hyperkalemia is accompanied by QRS widening. Which intervention first stabilizes the myocardium while potassium-lowering therapy is arranged?', 'Intravenous calcium using an appropriate monitored emergency protocol',[
 ('Nebulized salbutamol alone','It shifts potassium but does not provide the same immediate membrane stabilization.'),('Oral potassium binder alone','It is not immediate cardiac protection.'),('Insulin-glucose alone as a substitute for calcium','It lowers extracellular potassium but does not replace indicated membrane stabilization.')],
 'Protect the heart and lower potassium as parallel goals', '**Calcium antagonizes the electrical effects of hyperkalemia without removing potassium.**',['Repeat ECG assessment guides further action.','Insulin-glucose and definitive elimination must still follow.'], '**Use the correct calcium preparation and dose.**',['Ten-percent calcium gluconate and calcium chloride are not volume-equivalent.','RCUK 2025 specifies 30 mL gluconate or 10 mL chloride for this severe ECG-change context.'],[['Calcium','Membrane stabilization'],['Insulin/beta agonist','Intracellular shift'],['Dialysis/binders','Body potassium removal']],[RC,HK],'clinical_scenario')
q('Which statement about intravenous calcium in hyperkalemia is correct?', 'It can improve cardiac electrical stability without lowering the measured potassium concentration',[
 ('It permanently removes total body potassium','It does not remove potassium.'),('It makes repeat potassium testing unnecessary','Rebound and persistent hyperkalemia require monitoring.'),('It replaces dialysis when refractory severe hyperkalemia persists','Definitive elimination may still be urgent.')],
 'Do not confuse stabilization with elimination', '**The protective calcium effect is temporary.**',['ECG improvement does not establish biochemical correction.','Treat the cause and stop contributing potassium exposure.'], '**Arrange a sustained potassium-lowering strategy.**',['Check serial potassium and ECG.','Consider urgent dialysis when medical therapy is insufficient.'],[['Immediate electrical effect','Calcium'],['Measured potassium','May remain high'],['Definitive plan','Shift plus elimination']],[RC,HK])
q('What is a major preventable complication after insulin-glucose treatment of hyperkalemia?', 'Delayed hypoglycemia, particularly in kidney failure',[
 ('Permanent removal of potassium stores','Insulin shifts rather than removes potassium.'),('Obligatory severe hypercalcemia','This is not its characteristic effect.'),('Loss of all hypoglycemia risk after the first normal glucose reading','Hypoglycemia can occur later.')],
 'A normal early glucose does not finish monitoring', '**Insulin promotes cellular potassium uptake but can outlast the administered glucose load.**',['Reduced kidney clearance can prolong risk.','Baseline glucose affects supplemental glucose planning.'], '**Follow a structured serial glucose protocol.**',['Check potassium for response and rebound as well.','Provide additional glucose when indicated by the protocol and measurements.'],[['Benefit','Intracellular potassium shift'],['Hazard','Hypoglycemia'],['Monitoring','Serial glucose and potassium']],[HK,RC])
q('Why should nebulized beta-2 agonist therapy not be the only treatment of severe hyperkalemia?', 'The potassium response is variable and some patients respond poorly',[
 ('It cannot shift potassium in any patient','It can be a useful adjunct.'),('It always removes potassium through the stool','Its principal acute effect is cellular uptake.'),('It eliminates the need for ECG monitoring','Severe hyperkalemia remains an arrhythmia risk.')],
 'Combine complementary mechanisms', '**Beta-2 stimulation can increase cellular potassium uptake.**',['Tachycardia and ischemic risk can limit suitability.','Nonresponse makes sole reliance unsafe.'], '**Use alongside indicated cardiac protection and other measures.**',['Monitor clinical response.','Arrange actual potassium removal when needed.'],[['Role','Adjunctive shift'],['Limitation','Variable response'],['Definitive control','Elimination and cause correction']],[HK,RC])
q('Which patient most clearly needs urgent hemodialysis consideration for hyperkalemia?', 'A dialysis-dependent patient with severe persistent hyperkalemia despite temporizing therapy',[
 ('A stable patient with a mildly elevated hemolyzed value awaiting immediate repeat','Confirmation and risk assessment come first in that scenario.'),('A patient whose potassium is low after diarrhea','Dialysis for hyperkalemia is not indicated.'),('Every patient taking an ACE inhibitor with normal potassium','Exposure alone is not an indication.')],
 'Shifting buys time but does not remove the excess', '**Anuric patients have little native potassium elimination.**',['Insulin and beta agonists can be followed by rebound.','Access and dialysis availability should be addressed early.'], '**Continue stabilization while arranging treatment.**',['Review ECG and serial values.','Identify missed dialysis, tissue breakdown or medication triggers.'],[['Persistent severe elevation','Urgent definitive removal'],['Anuria','Limited native excretion'],['Shift therapy','Temporary bridge']],[HK,RC])
q('What is the role of sodium bicarbonate in acute hyperkalemia?', 'It is not routinely recommended as sole acute treatment; acid-base context may influence selected use',[
 ('It reliably replaces calcium for QRS widening','It does not substitute for indicated calcium.'),('It is universally effective regardless of pH','The potassium effect is variable.'),('It directly removes potassium without renal or gastrointestinal excretion','It is not a body-potassium removal mechanism.')],
 'The presence of acidosis changes interpretation, not the whole emergency algorithm', '**Bicarbonate is not the routine first-line acute potassium-lowering treatment.**',['Sodium and volume loads can be consequential.','Severe metabolic acidosis may create a separate indication.'], '**Do not delay proven emergency measures.**',['Stabilize ECG abnormalities and use indicated shift therapy.','Reassess acid-base status and definitive elimination.'],[['Routine acute role','Limited'],['Selected context','Significant metabolic acidosis'],['Risks','Sodium and volume burden']],[HK])
q('Which drug combination particularly increases hyperkalemia risk in CKD?', 'An ACE inhibitor plus a mineralocorticoid receptor antagonist',[
 ('A loop diuretic plus a thiazide through obligatory potassium retention','These generally increase potassium losses.'),('Insulin plus a beta-2 agonist through immediate extracellular potassium shift','Both usually shift potassium into cells.'),('Oral potassium binder plus a low-potassium supplement-free regimen','This does not carry the same pharmacological retention mechanism.')],
 'Reduced aldosterone signaling impairs distal potassium secretion', '**Risk rises with lower GFR, acute illness and additional potassium intake.**',['Trimethoprim and NSAIDs can further impair excretion.','Beneficial disease-modifying therapy should be managed rather than reflexively abandoned in all mild cases.'], '**Review reversible contributors and monitor.**',['Urgency depends on potassium severity and ECG findings.','A persistent problem may require dose changes or a potassium-lowering strategy.'],[['RAAS blockade','Reduced potassium secretion'],['CKD','Reduced reserve'],['Management','Severity-based medication and potassium plan']],[HK])
q('Hypokalemia, hypertension and metabolic alkalosis occur with low renin and high aldosterone. Which diagnosis is favored?', 'Primary aldosteronism',[
 ('Liddle syndrome','Liddle typically suppresses both renin and aldosterone.'),('Gitelman syndrome','Gitelman usually has normal or low blood pressure and secondary renin activation.'),('Gastrointestinal potassium loss alone','It does not explain autonomous aldosterone excess with this pattern.')],
 'Blood pressure and renin-aldosterone patterns narrow potassium-loss diagnoses', '**Autonomous aldosterone promotes sodium retention and potassium and hydrogen secretion.**',['Potassium can be normal in many affected patients.','Medications and hypokalemia can affect testing.'], '**Use an appropriate confirmatory and subtype pathway.**',['Do not choose surgery from the potassium pattern alone.','Review interfering treatments and potassium correction before interpretation.'],[['Primary aldosteronism','Low renin/high aldosterone'],['Liddle','Low renin/low aldosterone'],['Salt-losing tubulopathy','Renin often high']],[GS,HK])
q('A young hypertensive patient has hypokalemic alkalosis, suppressed renin and suppressed aldosterone. An inherited epithelial sodium channel gain-of-function is found. Which treatment is mechanistically targeted?', 'Amiloride',[
 ('Spironolactone as an equally direct receptor treatment of the channel defect','Aldosterone is suppressed; ENaC blockade targets the mechanism.'),('Fludrocortisone','This would worsen sodium retention and potassium loss.'),('A potassium binder','This would worsen hypokalemia.')],
 'Liddle syndrome acts downstream of the aldosterone receptor', '**Excess ENaC activity increases distal sodium reabsorption.**',['The lumen-negative potential promotes potassium and hydrogen secretion.','Low renin and aldosterone distinguish it from primary aldosteronism.'], '**Block the channel and address sodium intake.**',['Monitor potassium and renal function.','Evaluate the family when inherited disease is established.'],[['Defect','ENaC gain of function'],['Hormones','Renin and aldosterone suppressed'],['Target','Amiloride or triamterene']],[GS],'clinical_scenario')
q('An adolescent has hypokalemic alkalosis, hypomagnesemia, hypocalciuria and normal blood pressure. Which disorder is most likely?', 'Gitelman syndrome',[
 ('Classic Bartter syndrome with prominent hypercalciuria as the best fit','The calcium and magnesium pattern favors Gitelman, although overlap exists.'),('Liddle syndrome','Hypertension and suppressed renin-aldosterone are more characteristic.'),('Type 4 renal tubular acidosis','This usually causes hyperkalemic metabolic acidosis.')],
 'The distal convoluted tubule phenotype resembles chronic thiazide exposure', '**SLC12A3 loss impairs the sodium-chloride cotransporter.**',['Secondary renin-aldosterone activation promotes potassium loss.','Phenotype varies and genetic overlap can occur.'], '**Replace potassium and magnesium and review salt balance.**',['Adjunct drugs can worsen hypotension or salt depletion.','Do not label every hypokalemic patient Gitelman without excluding drugs and vomiting.'],[['Gitelman','Low magnesium and low urine calcium'],['Bartter','Often loop-like calcium phenotype'],['Blood pressure','Usually normal or low']],[GS],'clinical_scenario')
q('Hypokalemia remains refractory despite substantial potassium replacement. Which concurrent abnormality should be actively corrected?', 'Magnesium deficiency',[
 ('Mild isolated elevation of HDL cholesterol','This does not explain ongoing renal potassium wasting.'),('A high normal serum sodium alone','This is not a usual explanation for refractory replacement.'),('Low urine volume as proof that no renal loss can occur','Low volume does not establish appropriate potassium conservation.')],
 'Magnesium depletion sustains renal potassium loss', '**Low intracellular magnesium permits increased distal potassium secretion.**',['Serum magnesium may not perfectly reflect total stores.','Diuretics, diarrhea and poor intake often cause combined deficits.'], '**Replace both deficits safely.**',['Adjust replacement to kidney function.','Use ECG and serial electrolyte assessment according to severity.'],[['Potassium replacement failure','Check magnesium'],['Combined loss','Common with diuretics/diarrhea'],['Treatment','Correct both deficits']],[GS,EL],'clinical_scenario')
q('A patient has hypokalemic metabolic acidosis after prolonged watery diarrhea. Which accompanying renal response is expected if kidney acidification is intact?', 'Increased ammonium excretion and appropriate potassium conservation',[
 ('Inappropriately persistent renal potassium wasting as a required finding','Extrarenal loss should elicit conservation unless another process coexists.'),('Complete failure of ammonium excretion in every case','That would suggest a renal contribution.'),('A mandatory high urine pH proving distal RTA','Urine pH alone is not a reliable measure of total acid excretion.')],
 'Separate gastrointestinal loss from renal tubular disease', '**Diarrhea can remove both bicarbonate and potassium.**',['Appropriate ammonium excretion helps compensate for the acid load.','Urine potassium indices require interpretation with flow, intake and volume.'], '**Replace volume and electrolytes and stop the loss.**',['Mixed renal and extrarenal mechanisms are possible.','Use clinical context rather than a single urine cutoff alone.'],[['Loss site','Gastrointestinal'],['Acid-base','Normal-gap acidosis'],['Kidney response','Ammonium increase and potassium conservation']],[EL,GS],'clinical_scenario')
q('Which ECG pattern is classically associated with significant hypokalemia?', 'Flattened T waves, ST depression and prominent U waves',[
 ('Progressive peaked T waves and QRS widening as the characteristic early pattern','These suggest hyperkalemia.'),('Shortened QT from high calcium as the defining pattern','This is a hypercalcemic pattern.'),('A normal ECG excludes severe potassium depletion','ECG findings are variable and cannot exclude it.')],
 'Potassium depletion alters repolarization', '**Prominent U waves can make the apparent QT interval seem prolonged.**',['Ventricular arrhythmia risk rises with severe depletion and other cardiac risks.','Digoxin exposure and magnesium depletion are important modifiers.'], '**Treat the severity rather than the tracing alone.**',['Use monitored replacement when severe or symptomatic.','Check the cause and serial potassium.'],[['Low potassium','Flat T/prominent U'],['High potassium','Peaked T/conduction slowing'],['Risk','Arrhythmia']],[EL,RC])
q('Severe symptomatic hypokalemia requires intravenous replacement. Which administration principle is correct outside a cardiac-arrest protocol?', 'Use a controlled diluted infusion with appropriate monitoring; never give routine undiluted IV push potassium',[
 ('Give an undiluted rapid push to shorten treatment','This can cause fatal arrhythmia.'),('Use a universal rate without considering access or monitoring','Rate depends on severity, access and the monitored setting.'),('Stop checking potassium after the first bag','Overreplacement can occur, especially with kidney impairment.')],
 'Potassium is a high-alert intravenous medicine', '**Route, concentration and rate must follow a validated protocol.**',['Oral replacement is often preferred when feasible and urgency is lower.','Severe weakness, arrhythmia or inability to take oral therapy can justify IV treatment.'], '**Reassess renal function and ongoing losses.**',['Use ECG monitoring when indicated.','Cardiac arrest is a separate resuscitation context with specific guidance.'],[['Routine IV treatment','Controlled infusion'],['Safety','No undiluted push'],['Follow-up','Serial potassium and renal function']],[EL,RC])
q('Thyrotoxic periodic paralysis presents with potassium 2.1 mmol/L. Why should replacement be cautious?', 'The deficit is largely a transcellular shift, so excessive replacement can cause rebound hyperkalemia',[
 ('All patients have enormous fixed total-body potassium depletion','Shift predominates in typical periodic paralysis.'),('Thyrotoxicosis prevents potassium from returning extracellularly','The shift reverses with recovery.'),('Potassium replacement is always contraindicated despite arrhythmia','Severe disease can require carefully monitored replacement.')],
 'A low concentration does not always mean a large body deficit', '**Adrenergic and insulin-related cellular uptake contribute to the attack.**',['Carbohydrate intake and rest after exertion can precipitate episodes.','Clinical thyroid signs can be subtle.'], '**Treat the attack and the thyrotoxicosis.**',['Monitor potassium during recovery.','Appropriate beta blockade may help selected patients under supervision.'],[['Mechanism','Intracellular shift'],['Replacement hazard','Rebound hyperkalemia'],['Definitive prevention','Control thyrotoxicosis']],[EL,RC],'clinical_scenario')
q('Which finding most supports renal rather than extrarenal potassium loss during hypokalemia?', 'Inappropriately sustained urinary potassium excretion interpreted with current intake and renal function',[
 ('Any detectable urinary potassium proves renal wasting','Some urinary excretion is normal and context matters.'),('A spot concentration without considering urine dilution is definitive','Concentration is flow dependent.'),('Normal blood pressure excludes all renal wasting disorders','Gitelman, Bartter and drugs may cause wasting without hypertension.')],
 'Judge whether excretion is appropriate to the deficiency', '**Urine potassium-to-creatinine ratio or a timed collection can help.**',['Recent replacement and diuretics confound results.','Acid-base status and blood pressure guide the next differential.'], '**Integrate history and concurrent electrolytes.**',['Check magnesium and medications.','Avoid relying on TTKG without recognizing its physiological assumptions.'],[['Renal loss','Failure to conserve appropriately'],['Confounders','Replacement/diuretics'],['Next clues','Blood pressure and acid-base pattern']],[GS,EL])
q('A diabetic patient with CKD has persistent mild hyperkalemia and normal-anion-gap acidosis. Which mechanism is particularly likely?', 'Reduced aldosterone activity with impaired ammonium and distal potassium excretion',[
 ('A proximal bicarbonate leak with obligatory severe hypokalemia as the best fit','That describes a different RTA phenotype.'),('Excess aldosterone causing potassium retention','Aldosterone generally promotes potassium secretion.'),('Primary polydipsia causing hyperkalemic acidosis','This does not explain the combined defect.')],
 'Type 4 RTA links potassium and acid excretion', '**Hyporeninemic hypoaldosteronism is a classic diabetic setting.**',['Hyperkalemia itself suppresses renal ammoniagenesis.','RAAS blockers, NSAIDs and other drugs may contribute.'], '**Review causes and the clinical severity.**',['Manage potassium, acidosis and volume in an individualized way.','Do not assume every CKD-associated acidosis is type 4 RTA.'],[['Potassium','High'],['Acidosis','Usually normal gap'],['Mechanism','Aldosterone and ammonium impairment']],[HK],'clinical_scenario')
